/* Core: state, strings, helpers, router, events. */

var STORE_KEY = 'keysville-demo-v1';
var S = null;          // persisted state, seeded in data.js
var U = { v: {}, deskUser: null, menuOpen: false, a11yOpen: false, noticeSeen: false, route: { view: 'home', arg: '' } };
var views = {};
var desk = {};
var parts = {};
var on = { click: {}, submit: {}, change: {}, input: {} };
var STR = {};

function addStrings(map) {
  Object.keys(map).forEach(function (k) { STR[k] = map[k]; });
}

function lang() { return S && S.prefs.lang === 'es' && !(U.deskUser && isDeskView(U.route.view)) ? 'es' : 'en'; }

function t(key, vars) {
  var row = STR[key];
  var s = row ? (lang() === 'es' ? (row[1] || row[0]) : row[0]) : key;
  if (vars) {
    Object.keys(vars).forEach(function (k) {
      s = s.split('{' + k + '}').join(String(vars[k]));
    });
  }
  return s;
}

function L(field) {
  if (field == null) return '';
  if (typeof field === 'string') return field;
  return (lang() === 'es' && field.es) ? field.es : (field.en || '');
}

function LX(field) {
  if (typeof field === 'string') return { text: field, fallback: false };
  var missing = lang() === 'es' && !field.es;
  return { text: L(field), fallback: missing };
}

function esc(s) {
  return String(s == null ? '' : s)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;').replace(/'/g, '&#39;');
}

function icon(name, cls) {
  return '<svg class="ico' + (cls ? ' ' + cls : '') + '" aria-hidden="true" focusable="false"><use href="#i-' + name + '"></use></svg>';
}

var PASCAT_LOGO = 'data:image/png;base64,'+'';
var TOWN_LOGO = 'data:image/png;base64,';
var TOWN_LOGO_WHITE = 'data:image/png;base64,';
function townLogo(white) {
  return '<img class="town-logo" src="' + (white ? TOWN_LOGO_WHITE : TOWN_LOGO) + '" alt="' + esc(t('site_name')) + ', Virginia" width="363" height="92">';
}
function pascatLogo(cls) {
  return '<img class="pascat-logo' + (cls ? ' ' + cls : '') + '" src="' + PASCAT_LOGO + '" alt="Pascat Graphics &amp; Marketing" width="1721" height="324">';
}

function photo(shot, spec, size) {
  var label = t('photo_coming') + ' ' + shot;
  return '<div class="photo-req photo-req-' + (size || 'wide') + '" role="img" aria-label="' + esc(label) + '">' +
    '<div class="brand">' + pascatLogo('pascat-logo-sm') + '<b>' + t('photo_req') + '</b></div>' +
    '<p class="shot">' + esc(shot) + '</p>' +
    (spec ? '<p class="spec">' + esc(spec) + '</p>' : '') +
    '</div>';
}

function sampleTag() {
  return '<span class="tag tag-gold">' + t('sample') + '</span>';
}

function extLink(href, label, cls) {
  return '<a href="' + esc(href) + '" target="_blank" rel="noopener"' + (cls ? ' class="' + cls + '"' : '') + '>' +
    esc(label) + ' ' + icon('ext') + '<span class="sr-only"> (' + t('new_tab') + ')</span></a>';
}

function link(view, arg, inner, cls, extra) {
  var href = '#' + view + (arg ? '-' + arg : '');
  return '<a href="' + href + '" data-go="' + view + '"' + (arg ? ' data-arg="' + esc(arg) + '"' : '') +
    (cls ? ' class="' + cls + '"' : '') + (extra ? ' ' + extra : '') + '>' + inner + '</a>';
}

function go(view, arg) {
  location.hash = view + (arg ? '-' + arg : '');
}

function pageHead(o) {
  var crumbs = '';
  if (o.crumbs && o.crumbs.length) {
    crumbs = '<nav aria-label="' + t('breadcrumb') + '"><ol class="crumbs">' +
      o.crumbs.map(function (c) { return '<li>' + link(c[0], c[2] || '', esc(c[1])) + '</li>'; }).join('') +
      '<li aria-current="page">' + esc(o.title) + '</li></ol></nav>';
  }
  return '<div class="wrap page-head">' + crumbs +
    (o.eyebrow ? '<p class="eyebrow">' + esc(o.eyebrow) + '</p>' : '') +
    '<div class="section-head"><h1>' + esc(o.title) + '</h1>' + (o.aside || '') + '</div>' +
    (o.lead ? '<p class="lead">' + esc(o.lead) + '</p>' : '') +
    '</div>';
}

/* Dates */
var MONTHS = { en: ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'],
  es: ['enero', 'febrero', 'marzo', 'abril', 'mayo', 'junio', 'julio', 'agosto', 'septiembre', 'octubre', 'noviembre', 'diciembre'] };
var MONTHS_S = { en: ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'],
  es: ['ene', 'feb', 'mar', 'abr', 'may', 'jun', 'jul', 'ago', 'sep', 'oct', 'nov', 'dic'] };
var DAYS = { en: ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'],
  es: ['domingo', 'lunes', 'martes', 'miércoles', 'jueves', 'viernes', 'sábado'] };
var DAYS_S = { en: ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'], es: ['dom', 'lun', 'mar', 'mié', 'jue', 'vie', 'sáb'] };

function parseISO(iso) {
  var p = String(iso).split('-').map(Number);
  return new Date(p[0], p[1] - 1, p[2]);
}
function toISO(d) {
  var m = d.getMonth() + 1, day = d.getDate();
  return d.getFullYear() + '-' + (m < 10 ? '0' : '') + m + '-' + (day < 10 ? '0' : '') + day;
}
function todayISO() { return toISO(new Date()); }
function addDays(iso, n) { var d = parseISO(iso); d.setDate(d.getDate() + n); return toISO(d); }

function fmtDate(iso, style) {
  if (!iso) return '';
  var d = parseISO(iso), l = lang();
  var mo = MONTHS[l][d.getMonth()], ms = MONTHS_S[l][d.getMonth()], day = d.getDate(), y = d.getFullYear();
  if (style === 'short') return l === 'es' ? day + ' ' + ms + ' ' + y : ms + ' ' + day + ', ' + y;
  if (style === 'day') return l === 'es' ? day + ' de ' + mo : mo + ' ' + day;
  if (style === 'monthday') return l === 'es' ? day + ' ' + ms : ms + ' ' + day;
  if (style === 'weekday') return l === 'es' ? DAYS[l][d.getDay()] + ' ' + day + ' de ' + mo : DAYS[l][d.getDay()] + ', ' + mo + ' ' + day;
  return l === 'es' ? day + ' de ' + mo + ' de ' + y : mo + ' ' + day + ', ' + y;
}
function fmtTime(hhmm) {
  if (!hhmm) return '';
  var p = hhmm.split(':'), h = Number(p[0]), m = p[1];
  var ap = h >= 12 ? 'p.m.' : 'a.m.';
  var h12 = h % 12 === 0 ? 12 : h % 12;
  return h12 + ':' + m + ' ' + ap;
}
function fmtDateTime(ts) {
  var d = new Date(ts);
  var hh = d.getHours(), mm = d.getMinutes();
  return fmtDate(toISO(d), 'short') + ', ' + fmtTime((hh < 10 ? '0' : '') + hh + ':' + (mm < 10 ? '0' : '') + mm);
}
function ago(ts) {
  var m = Math.round((Date.now() - ts) / 60000);
  if (m < 1) return t('just_now');
  if (m < 60) return t('min_ago', { n: m });
  var h = Math.round(m / 60);
  if (h < 24) return t('hr_ago', { n: h });
  var d = Math.round(h / 24);
  return d === 1 ? t('day_ago_1') : t('day_ago', { n: d });
}
function isWorkingDay(iso) {
  var d = parseISO(iso).getDay();
  return d !== 0 && d !== 6 && S.holidays.indexOf(iso) === -1;
}
function workingDaysAfter(iso, n) {
  var cur = iso, left = Math.abs(n), step = n < 0 ? -1 : 1;
  while (left > 0) { cur = addDays(cur, step); if (isWorkingDay(cur)) left--; }
  return cur;
}
function workingDaysBetween(a, b) {
  var cur = a, n = 0, dir = parseISO(b) >= parseISO(a) ? 1 : -1;
  while (cur !== b) { cur = addDays(cur, dir); if (isWorkingDay(cur)) n += dir; }
  return n;
}

/* Persistence */
function save() {
  try { localStorage.setItem(STORE_KEY, JSON.stringify(S)); } catch (e) { /* storage may be blocked; the demo still runs */ }
}
function load() {
  try {
    var raw = localStorage.getItem(STORE_KEY);
    if (raw) { var o = JSON.parse(raw); if (o && o.v === SEED_VERSION) return o; }
  } catch (e) { /* ignore */ }
  return null;
}
function resetDemo() {
  try { localStorage.removeItem(STORE_KEY); } catch (e) { /* ignore */ }
  S = seed();
  save();
  applyPrefs();
  toast(t('demo_reset'), 'ok');
  route();
}

/* Announcements */
function announce(msg) {
  var el = document.getElementById('live');
  if (!el) return;
  el.textContent = '';
  setTimeout(function () { el.textContent = msg; }, 50);
}
function toast(msg, kind) {
  var box = document.getElementById('toasts');
  if (!box) return;
  var el = document.createElement('div');
  el.className = 'toast' + (kind ? ' toast-' + kind : '');
  el.textContent = msg;
  box.appendChild(el);
  announce(msg);
  setTimeout(function () { if (el.parentNode) el.parentNode.removeChild(el); }, 5000);
}

/* Tickets and routing */
function newRef() {
  var n = S.nextRef++;
  save();
  return 'K-' + n;
}
function findTicket(ref) {
  var r = String(ref || '').trim().toUpperCase().replace(/\s+/g, '');
  if (/^\d+$/.test(r)) r = 'K-' + r;
  for (var i = 0; i < S.tickets.length; i++) if (S.tickets[i].ref === r) return S.tickets[i];
  return null;
}
function routeFor(cat) { return S.routes[cat] || 'clerk'; }
function deptName(key) { var d = S.depts[key]; return d ? L(d.name) : key; }
function openTicket(o) {
  var ref = newRef();
  var tk = {
    ref: ref, cat: o.cat || 'other', dept: o.dept || routeFor(o.cat || 'other'), status: 'new', created: Date.now(),
    name: o.name || '', contact: o.contact || '', where: o.where || '', text: o.text || '', lang: lang(),
    source: o.source || 'contact', due: o.due || null,
    timeline: [{ t: Date.now(), who: 'resident', text: o.text || '', public: true },
      { t: Date.now() + 1, who: 'system', dept: o.dept || routeFor(o.cat || 'other'), text: '', public: true }]
  };
  S.tickets.unshift(tk);
  logAct('New request ' + ref + ' (' + tk.cat + ') sent to ' + S.depts[tk.dept].name.en);
  save();
  return tk;
}
function logAct(text) {
  S.log.unshift({ t: Date.now(), who: U.deskUser ? U.deskUser.name : 'Resident (website)', text: text });
  if (S.log.length > 200) S.log.length = 200;
}

/* Alerts */
function liveAlerts() {
  var now = Date.now();
  return S.alerts.filter(function (a) { return !a.down && a.start <= now && (!a.end || a.end > now); })
    .sort(function (a, b) { return levelRank(b.level) - levelRank(a.level) || b.start - a.start; });
}
function levelRank(l) { return l === 'emergency' ? 3 : l === 'advisory' ? 2 : 1; }
function tickAlerts() {
  var now = Date.now(), changed = false;
  S.alerts.forEach(function (a) { if (!a.down && a.end && a.end <= now) { a.down = true; changed = true; logAct('Alert expired on its own: ' + a.head.en); } });
  if (changed) { save(); if (!(document.activeElement && closest(document.activeElement, 'form'))) rerender(); }
}

/* Calendar helpers */
function allItemsOn(iso) {
  var out = [];
  S.meetings.forEach(function (m) { if (m.date === iso) out.push({ kind: 'meeting', date: m.date, time: m.time, title: meetingTitle(m), ref: m }); });
  S.events.forEach(function (e) { if (e.date === iso) out.push({ kind: e.kind, date: e.date, time: e.time, title: L(e.title), ref: e }); });
  return out.sort(function (a, b) { return (a.time || '').localeCompare(b.time || ''); });
}
function upcoming(n) {
  var today = todayISO(), out = [];
  S.meetings.forEach(function (m) { if (m.date >= today && m.status !== 'cancelled') out.push({ kind: 'meeting', date: m.date, time: m.time, title: meetingTitle(m), ref: m }); });
  S.events.forEach(function (e) { if (e.date >= today) out.push({ kind: e.kind, date: e.date, time: e.time, title: L(e.title), ref: e }); });
  out.sort(function (a, b) { return a.date.localeCompare(b.date) || (a.time || '').localeCompare(b.time || ''); });
  return n ? out.slice(0, n) : out;
}
function bodyName(key) {
  return t('body_' + key);
}
function meetingTitle(m) {
  return bodyName(m.body) + ' ' + t('kind_' + m.kind);
}

/* A timeline entry's text in the reader's language */
function entryText(e) {
  if (e.dept) return t('sent_to', { dept: deptName(e.dept) });
  return e.text || '';
}

/* Shared blocks */
function humanStrip() {
  return '<aside class="callout callout-pine human-strip" aria-label="' + esc(t('human_title')) + '">' +
    '<p><strong>' + t('human_title') + '</strong> ' + t('human_body') + '</p>' +
    '<p class="small">' + t('human_relay') + ' ' + link('contact', 'callback', t('human_callback')) + '</p></aside>';
}
function formNotes() {
  return '<p class="form-privacy">' + t('form_foia') + ' ' + link('legal', 'privacy', t('form_privacy')) + '</p>';
}

/* Assistant wrapper. The host page may provide window.PascatAssist with a
   use(name) method that resolves to a text-generation function; without it
   the assistant falls back to the built-in keyword answers. */
var AI = (function () {
  var fn = null, resolved = false, waiting = null;
  function get() {
    if (resolved) return Promise.resolve(fn);
    if (waiting) return waiting;
    waiting = (window.PascatAssist && window.PascatAssist.use ? window.PascatAssist.use('sample') : Promise.resolve(null))
      .then(function (f) { fn = f || null; resolved = true; return fn; })
      .catch(function () { fn = null; resolved = true; return null; });
    return waiting;
  }
  return {
    available: function () { return get().then(function (f) { return !!f; }); },
    ask: function (prompt, o) {
      o = o || {};
      return get().then(function (f) {
        if (!f) return Promise.reject({ code: 'not_available' });
        return f(prompt, { onText: o.onText, signal: o.signal, modelTier: o.tier || 'quick', cache: o.cache === undefined ? false : o.cache })
          .then(function (r) { return r.text; });
      });
    }
  };
})();

function siteKnowledge() {
  var lines = [];
  lines.push('TOWN: Town of Keysville, Virginia (Charlotte County). Zip 23947. Town Hall: 120 J Street, Keysville VA 23947 (mail: P.O. Box 42). Phone 434-736-9551. Hours 8:30 a.m. to 3:00 p.m., Monday to Friday. Population 807.');
  lines.push('ALERTS NOW: ' + (liveAlerts().map(function (a) { return a.level + ': ' + a.head.en + ' ' + a.body.en; }).join(' | ') || 'none'));
  lines.push('DEPARTMENTS: ' + Object.keys(S.depts).map(function (k) { return S.depts[k].name.en + (S.depts[k].phone ? ' ' + S.depts[k].phone : ''); }).join('; '));
  lines.push('UPCOMING: ' + upcoming(6).map(function (u) { return u.date + ' ' + (u.time || '') + ' ' + u.title; }).join('; '));
  lines.push('ANSWERS:');
  S.articles.forEach(function (a) { lines.push('- [' + a.id + '] ' + a.title.en + ': ' + a.body.en.replace(/\s+/g, ' ').slice(0, 600) + ' (reviewed ' + a.reviewed + ')'); });
  return lines.join('\n');
}

/* Speech */
var speaking = null;
function canSpeak() { return 'speechSynthesis' in window; }
function speak(text) {
  if (!canSpeak()) return;
  stopSpeaking();
  var u = new SpeechSynthesisUtterance(text);
  u.lang = lang() === 'es' ? 'es-US' : 'en-US';
  u.rate = 0.95;
  speaking = u;
  window.speechSynthesis.speak(u);
}
function stopSpeaking() {
  if (canSpeak()) window.speechSynthesis.cancel();
  speaking = null;
}

/* Preferences */
function applyPrefs() {
  var h = document.documentElement, p = S.prefs;
  h.lang = lang();
  h.className = h.className.replace(/\b(size-\d|hc|easy|simple|calm)\b/g, '').trim();
  if (p.size) h.classList.add('size-' + p.size);
  if (p.contrast) h.classList.add('hc');
  if (p.easy) h.classList.add('easy');
  if (p.simple) h.classList.add('simple');
  if (p.calm) h.classList.add('calm');
}
function setPref(key, val) {
  S.prefs[key] = val;
  save();
  applyPrefs();
  rerender();
}

/* Router */
function parseHash() {
  var h = (location.hash || '#home').slice(1);
  var m = h.match(/^([a-z]+)(?:-([A-Za-z0-9._~-]+))?$/);
  if (!m) return { view: 'home', arg: '' };
  return { view: m[1], arg: m[2] || '' };
}
function isDeskView(v) { return v === 'desklogin' || !!desk[v]; }

function route() {
  var r = parseHash();
  var prev = U.route;
  U.route = r;
  U.menuOpen = false;
  stopSpeaking();
  render();
  if (prev.view !== r.view || prev.arg !== r.arg) {
    window.scrollTo(0, 0);
    var main = document.getElementById('main');
    if (main) main.focus({ preventScroll: true });
  }
}

function render() {
  var r = U.route, app = document.getElementById('app');
  var html, title;
  document.documentElement.lang = lang();  // Town Desk is English even when the public side is Spanish
  if (isDeskView(r.view)) {
    if (!U.deskUser && r.view !== 'desklogin') { html = renderLogin(r.view); title = 'Sign in'; }
    else if (r.view === 'desklogin') { html = renderLogin('desk'); title = 'Sign in'; }
    else { var dv = desk[r.view]; title = dv.title(r.arg); html = renderDeskShell(r.view, dv.render(r.arg)); }
    document.title = title + ' | Town Desk';
  } else {
    var v = views[r.view] || views.notfound || views.home;
    title = v.title(r.arg);
    html = renderPublicShell(v, r.arg);
    document.title = title + ' | ' + t('site_name');
  }
  app.innerHTML = html;
  labelTableCells(app);
  var v2 = isDeskView(r.view) ? desk[r.view] : (views[r.view] || views.notfound || views.home);
  if (v2 && v2.after && (U.deskUser || !isDeskView(r.view))) v2.after(r.arg);
  announce(title);
}

/* Phones stack table rows into cards; each cell needs its column name. */
function labelTableCells(root) {
  var tables = root.querySelectorAll('table.table');
  for (var i = 0; i < tables.length; i++) {
    var heads = tables[i].querySelectorAll('thead th');
    if (!heads.length) continue;
    var names = Array.prototype.map.call(heads, function (th) { return th.textContent.trim(); });
    var rows = tables[i].querySelectorAll('tbody tr');
    for (var r = 0; r < rows.length; r++) {
      var cells = rows[r].children;
      for (var c = 0; c < cells.length && c < names.length; c++) {
        if (cells[c].tagName === 'TD' && names[c]) cells[c].setAttribute('data-th', names[c]);
      }
    }
  }
}

function rerender() {
  var active = document.activeElement, id = active && active.id, pos = window.scrollY;
  render();
  if (id) { var el = document.getElementById(id); if (el) el.focus({ preventScroll: true }); }
  window.scrollTo(0, pos);
}
function refresh(name) {
  var el = document.querySelector('[data-part="' + name + '"]');
  if (el && parts[name]) { el.innerHTML = parts[name](); labelTableCells(el); }
}

/* Delegated events */
function closest(el, sel) { while (el && el.nodeType === 1) { if (el.matches(sel)) return el; el = el.parentElement; } return null; }

function handleClick(e) {
  var a = closest(e.target, 'a[data-go]');
  if (a) {
    // Let the browser handle the hash change; it drives the router.
    return;
  }
  var b = closest(e.target, '[data-act]');
  if (b) {
    var fn = on.click[b.getAttribute('data-act')];
    if (fn) { e.preventDefault(); fn(b, e); }
  }
}
function handleSubmit(e) {
  var f = closest(e.target, 'form');
  if (!f) return;
  e.preventDefault();
  var name = f.getAttribute('data-form');
  var fn = name && on.submit[name];
  if (!fn) return;
  var data = {};
  Array.prototype.forEach.call(f.elements, function (el) {
    if (!el.name) return;
    if (el.type === 'checkbox') { if (el.checked) data[el.name] = data[el.name] ? data[el.name] + ',' + el.value : el.value; return; }
    if (el.type === 'radio') { if (el.checked) data[el.name] = el.value; return; }
    data[el.name] = el.value;
  });
  fn(f, data, e);
}
function handleChange(e) {
  var el = closest(e.target, '[data-change]');
  if (el) { var fn = on.change[el.getAttribute('data-change')]; if (fn) fn(el, e); }
}
function handleInput(e) {
  var el = closest(e.target, '[data-input]');
  if (el) { var fn = on.input[el.getAttribute('data-input')]; if (fn) fn(el, e); }
}
function handleKey(e) {
  if (e.key === 'Escape') {
    if (U.a11yOpen) { U.a11yOpen = false; rerender(); var b = document.getElementById('a11y-fab'); if (b) b.focus(); }
    else if (U.menuOpen) { U.menuOpen = false; rerender(); var m = document.getElementById('nav-toggle'); if (m) m.focus(); }
  }
}

/* Simple form validation: returns a list of problems and marks fields */
function validate(form, rules) {
  var errs = [];
  rules.forEach(function (r) {
    var el = form.elements[r.name];
    if (!el) return;
    var group = typeof el.length === 'number' && !el.tagName;
    var v = group ? Array.prototype.filter.call(el, function (x) { return x.checked; }).map(function (x) { return x.value; }).join(',')
      : (el.type === 'checkbox' ? (el.checked ? el.value : '') : (el.value || '').trim());
    var bad = (r.required && !v) || (r.pattern && v && !r.pattern.test(v)) || (r.min && v.length < r.min);
    if (group) el = el[0];
    var errEl = form.querySelector('[data-err="' + r.name + '"]');
    if (bad) {
      errs.push({ name: r.name, msg: r.msg, el: el });
      el.setAttribute('aria-invalid', 'true');
      if (errEl) { errEl.textContent = r.msg; errEl.hidden = false; }
    } else {
      el.removeAttribute('aria-invalid');
      if (errEl) { errEl.textContent = ''; errEl.hidden = true; }
    }
  });
  var summary = form.querySelector('[data-errsummary]');
  if (summary) {
    if (errs.length) {
      summary.hidden = false;
      summary.innerHTML = '<p><strong>' + esc(t('fix_these')) + '</strong></p><ul>' + errs.map(function (x) { return '<li>' + esc(x.msg) + '</li>'; }).join('') + '</ul>';
      summary.focus();
    } else { summary.hidden = true; summary.innerHTML = ''; }
  } else if (errs.length) { errs[0].el.focus(); }
  return errs;
}

